def find_solutions(limit):
    solutions = []
    # 2^a2 * 5^b2 - 2^a1 * 5^b1 = 50
    # a1+a2 = a, b1+b2 = b
    # we search a1, a2, b1, b2 in a reasonable range
    for a1 in range(limit):
        for a2 in range(limit):
            for b1 in range(limit):
                for b2 in range(limit):
                    val = (2**a2) * (5**b2) - (2**a1) * (5**b1)
                    if val == 50:
                        a = a1 + a2
                        b = b1 + b2
                        # N-25 = x = 2^a1 * 5^b1
                        N = (2**a1) * (5**b1) + 25
                        solutions.append((a, b, N))
    return solutions

print(find_solutions(15))

def find_all_solutions(limit):
    solutions = []
    for a in range(limit):
        for b in range(limit):
            # N^2 = 2^a * 5^b + 625
            rhs = 2**a * 5**b + 625
            N = int(rhs**0.5)
            if N*N == rhs:
                solutions.append((a, b, N))
                solutions.append((a, b, -N))
    return solutions

print(find_all_solutions(30))
